void on_the_phone_option_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_on_the_phone_option_obj_t * p_screen_param;
    lv_obj_t *      list = get_on_the_phone_option_list_obj(ui_Screen);
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;

    p_screen_param      = (ui_screen_on_the_phone_option_obj_t *) lv_obj_get_user_data(ui_Screen);

    __inf("on_the_phone_option_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);

    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }
                }
            break;

        case LV_KEY_ENTER:
        case APP_KEY_VALUE_TOP_LEFT:
            {
                switch (child_id)
                {
                    case ENUM_PHONE_HANGUP:
                        alv_am_win_jump_action(NULL,"hangup",&p_screen_param->enter_param);
                        call_fp_flow_hungup(handle_hungup_result);
                        break;

                    case ENUM_PHONE_MUTE:
                        {
                            uint32_t        is_mute_ul;

                            is_mute_ul          = g_audio_is_mute_ul;

                            if (is_mute_ul)
                                is_mute_ul = 0;
                            else 
                                is_mute_ul = 1;

                            audio_mute_ul(is_mute_ul);
                            g_audio_is_mute_ul  = is_mute_ul;

                            alv_am_win_exit_current(NULL);
                            }
                        break;

                    case ENUM_PHONE_SPEAKER:
                        {
                            u32             out_device;

                            audio_get_device(NULL,&out_device);

                            __inf("audio_get_device:%d",out_device);

                            if (out_device != 2) {
                                audio_force_out_device(2); //AUDIO_DEVICE_OUT_SPEAKER

                                //lv_label_set_text(p_screen_param->obj_label[OBJ_LABEL_HANDFREE], "免提");
                                call_fp_flow_set_call_volume(call_fp_flow_get_call_volume());
                                }
                            else {
                                audio_force_out_device(1); //AUDIO_DEVICE_OUT_HEADPHONE//AUDIO_DEVICE_OUT_EARPIECE

                                //lv_label_set_text(p_screen_param->obj_label[OBJ_LABEL_HANDFREE], "听筒");
                                call_fp_flow_set_call_volume(call_fp_flow_get_call_volume());
                                }

                            alv_am_win_exit_current(NULL);
                            }
                        break;

                    case ENUM_PHONE_RECORD:
                        {
                            lv_obj_t *      p_cur_app,*p_win,*ui_phone;

                            if (0 == sdmmc_get_card_status()) {
                                //on_the_phone_tf_remind_screen(ui_Screen);
                                create_comp_msgbox_remind("请插入T卡");
                                break;
                                }

                            if (0 == sd_storage_space_is_enough()) {
                                create_comp_msgbox_remind("内存空间不足!");
                                break;
                                }

                            p_cur_app           = get_app_by_name("call");
                            p_win               = get_win_by_name(p_cur_app,"on_the_phone");
                            ui_phone            = lv_obj_get_user_data(p_win);

                            if (ui_phone) {
                                on_the_phone_record_start_stop(ui_phone);
                                }

                            alv_am_win_exit_current(NULL);
                            }
                        break;

                    default:
                        break;
                    }
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);

                }
            break;

        default:
            break;
        }
}






